import java.util.*; import java.io.*; public class Main { static class FastScanner { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st; String next() { while (st == null || !st.hasMoreTokens()) { try { String l = br.readLine(); if (l == null) return null; st = new StringTokenizer(l); } catch (IOException e) { return null; } } return st.nextToken(); } int nextInt() { return Integer.parseInt(next()); } } public static void main(String[] args) throws Exception { FastScanner sc = new FastScanner(); int t = sc.nextInt(); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { int n = sc.nextInt(); String a = sc.next(); String b = sc.next(); int chefScore = 0; int chefinaScore = 0; int losses = 0; int draws = 0; for (int i = 0; i < n; i++) { char c = a.charAt(i); char f = b.charAt(i); if (c == f) { draws++; } else if ((c == 'R' && f == 'S') || (c == 'S' && f == 'P') || (c == 'P' && f == 'R')) { chefScore++; } else { chefinaScore++; losses++; } } int diff = chefScore - chefinaScore; int changes = 0; while (diff <= 0) { if (losses > 0) { diff += 2; losses--; } else { diff += 1; draws--; } changes++; } out.println(changes); } out.flush(); out.close(); } }